  "{0} pictures. Tap one to make the page.": { es: "{0} dibujos. Toca uno para crear la página.", ar: "{0} صورة. انقر على واحدة لصنع الصفحة.", zh: "共 {0} 张图片。点一张即可生成页面。", sw: "Picha {0}. Gusa moja kutengeneza ukurasa.", sv: "{0} bilder. Tryck på en för att göra sidan.", de: "{0} Bilder. Tippe auf eines, um die Seite zu erstellen.", pt: "{0} desenhos. Toque em um para criar a página.", fr: "{0} images. Touchez-en une pour créer la page." },
  "{0} pictures found (of {1}). Tap one to make the page.": { es: "{0} dibujos encontrados (de {1}). Toca uno para crear la página.", ar: "وُجدت {0} صورة (من {1}). انقر على واحدة لصنع الصفحة.", zh: "找到 {0} 张图片（共 {1} 张）。点一张即可生成页面。", sw: "Picha {0} zimepatikana (kati ya {1}). Gusa moja kutengeneza ukurasa.", sv: "{0} bilder hittades (av {1}). Tryck på en för att göra sidan.", de: "{0} Bilder gefunden (von {1}). Tippe auf eines, um die Seite zu erstellen.", pt: "{0} desenhos encontrados (de {1}). Toque em um para criar a página.", fr: "{0} images trouvées (sur {1}). Touchez-en une pour créer la page." },
