  "Letter and word tracing": { es: "Repasar letras y palabras", ar: "تتبّع الحروف والكلمات", zh: "字母和单词描写", sw: "Kufuatilia herufi na maneno", sv: "Skriva efter bokstäver och ord", de: "Buchstaben und Wörter nachspuren", pt: "Cobrir letras e palavras", fr: "Tracé de lettres et de mots" },
