  "Hard (ages 8+)": { es: "Difícil (8+ años)", ar: "صعب (8 سنوات فأكثر)", zh: "困难（8 岁以上）", sw: "Ngumu (miaka 8+)", sv: "Svår (8+ år)", de: "Schwer (ab 8 Jahren)", pt: "Difícil (8+ anos)", fr: "Difficile (8 ans et +)" },
