  "Add a page with the answer": { es: "Añadir una página con la solución", ar: "أضف صفحة بالحل", zh: "添加一页答案", sw: "Ongeza ukurasa wenye jibu", sv: "Lägg till en sida med lösningen", de: "Seite mit der Lösung hinzufügen", pt: "Adicionar uma página com a resposta", fr: "Ajouter une page avec la solution" },
  "Make a maze": { es: "Crear un laberinto", ar: "اصنع متاهة", zh: "生成迷宫", sw: "Tengeneza kitendawili cha njia", sv: "Gör en labyrint", de: "Labyrinth erstellen", pt: "Criar um labirinto", fr: "Créer un labyrinthe" },
  "Book cover": { es: "Portada del libro", ar: "غلاف الكتاب", zh: "书封面", sw: "Jalada la kitabu", sv: "Bokomslag", de: "Buchcover", pt: "Capa do livro", fr: "Couverture du livre" },
  "Small line underneath": { es: "Línea pequeña debajo", ar: "سطر صغير تحتها", zh: "下方的小字", sw: "Mstari mdogo chini yake", sv: "Liten rad under", de: "Kleine Zeile darunter", pt: "Linha pequena embaixo", fr: "Petite ligne en dessous" },
  "Make the cover": { es: "Crear la portada", ar: "اصنع الغلاف", zh: "生成封面", sw: "Tengeneza jalada", sv: "Gör omslaget", de: "Titelseite erstellen", pt: "Criar a capa", fr: "Créer la couverture" },
  "Your page appears here. Choose what to make on the left and press the button.": { es: "Tu página aparece aquí. Elige a la izquierda qué crear y pulsa el botón.", ar: "تظهر صفحتك هنا. اختر ما تريد صنعه على اليسار واضغط الزر.", zh: "你的页面会显示在这里。在左边选择要做什么，然后按按钮。", sw: "Ukurasa wako unaonekana hapa. Chagua cha kutengeneza upande wa kushoto na ubonyeze kitufe.", sv: "Din sida visas här. Välj vad du vill göra till vänster och tryck på knappen.", de: "Deine Seite erscheint hier. Wähle links, was du erstellen willst, und tippe auf den Knopf.", pt: "Sua página aparece aqui. Escolha o que criar à esquerda e toque no botão.", fr: "Votre page apparaît ici. Choisissez quoi créer à gauche et appuyez sur le bouton." },
  "➕ Add to book": { es: "➕ Añadir al libro", ar: "➕ أضف إلى الكتاب", zh: "➕ 加入书中", sw: "➕ Ongeza kwenye kitabu", sv: "➕ Lägg till i boken", de: "➕ Ins Buch", pt: "➕ Adicionar ao livro", fr: "➕ Ajouter au livre" },
  "Download page (PNG)": { es: "Descargar página (PNG)", ar: "نزّل الصفحة (PNG)", zh: "下载页面（PNG）", sw: "Pakua ukurasa (PNG)", sv: "Ladda ner sidan (PNG)", de: "Seite herunterladen (PNG)", pt: "Baixar página (PNG)", fr: "Télécharger la page (PNG)" },
  "Download as PDF": { es: "Descargar como PDF", ar: "نزّل كملف PDF", zh: "下载为 PDF", sw: "Pakua kama PDF", sv: "Ladda ner som PDF", de: "Als PDF herunterladen", pt: "Baixar como PDF", fr: "Télécharger en PDF" },
  "🖨 Print": { es: "🖨 Imprimir", ar: "🖨 طباعة", zh: "🖨 打印", sw: "🖨 Chapisha", sv: "🖨 Skriv ut", de: "🖨 Drucken", pt: "🖨 Imprimir", fr: "🖨 Imprimer" },
  "Your coloring book": { es: "Tu libro para colorear", ar: "كتاب التلوين الخاص بك", zh: "你的涂色书", sw: "Kitabu chako cha kupaka rangi", sv: "Din målarbok", de: "Dein Malbuch", pt: "Seu livro de colorir", fr: "Votre cahier de coloriage" },
